const inquiryForm=document.getElementById('enrollment-form');const inquiryStatus=document.getElementById('enrollment-status');const inquirySubmit=document.getElementById('enrollment-submit');const contact=window.academyContact||{};const approvedEmail=/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(contact.email||'')?contact.email:'';const approvedWhatsapp=/^\d{8,15}$/.test(contact.whatsapp||'')?contact.whatsapp:'';const bilingual=(en,tr)=>courseLanguage()==='tr'?tr:en;
const route=document.createElement('select');route.id='inquiry-route';route.name='route';const routeLabel=document.createElement('label');routeLabel.htmlFor=route.id;inquirySubmit.before(routeLabel,route);function enrollmentLabels(){routeLabel.textContent=bilingual('Choose how to continue','Nasıl devam etmek istersiniz?');const selected=route.value;route.replaceChildren();for(const [value,en,tr]of [...(approvedEmail?[['email','Open email draft','E-posta taslağını aç']]:[]),...(approvedWhatsapp?[['whatsapp','Open WhatsApp draft','WhatsApp taslağını aç']]:[]),['download','Download inquiry draft','Talep taslağını indir']]){const option=document.createElement('option');option.value=value;option.textContent=bilingual(en,tr);route.append(option)}if([...route.options].some(o=>o.value===selected))route.value=selected;document.getElementById('enrollment-note').textContent=approvedEmail||approvedWhatsapp?bilingual('Your details stay in this browser until you choose a channel. You review and send the message yourself.','Bir iletişim kanalı seçene kadar bilgileriniz bu tarayıcıda kalır. Mesajı kendiniz kontrol eder ve gönderirsiniz.'):bilingual('Email and WhatsApp enrollment channels are being prepared. You can download your inquiry draft now. Nothing is submitted or stored by the academy.','E-posta ve WhatsApp başvuru kanalları hazırlanıyor. Şimdilik talep taslağınızı indirebilirsiniz. Akademiye hiçbir bilgi gönderilmez veya akademi tarafından saklanmaz.');inquirySubmit.textContent=bilingual('Prepare inquiry ↗','Bilgi talebini hazırla ↗');inquiryStatus.textContent=''}window.addEventListener('languagechange',enrollmentLabels);enrollmentLabels();inquiryForm.addEventListener('submit',event=>{event.preventDefault();if(!inquiryForm.reportValidity())return;const data=new FormData(inquiryForm);const body=[bilingual('Control Valve Engineering Course — enrollment inquiry','Kontrol Vanası Mühendisliği Eğitimi — başvuru talebi'),'Mahjoub Academy','',`${bilingual('Name','Ad soyad')}: ${data.get('name').trim()}`,`${bilingual('Email','E-posta')}: ${data.get('email').trim()}`,`${bilingual('Role / company','Görev / şirket')}: ${data.get('role').trim()}`,'',bilingual('Please share the next course dates, delivery format, fees and availability.','Lütfen bir sonraki eğitimin tarihlerini, eğitim şeklini, ücretini ve kontenjan bilgisini paylaşın.'),'',data.get('message').trim()].join('\n');if(route.value==='email'&&approvedEmail){const a=document.createElement('a');a.href=`mailto:${approvedEmail}?subject=${encodeURIComponent(bilingual('Control Valve Course — Enrollment Inquiry','Kontrol Vanası Eğitimi — Başvuru Talebi'))}&body=${encodeURIComponent(body)}`;a.click();inquiryStatus.textContent=bilingual('Your email draft is ready in your mail app. Review it and send it to complete your inquiry.','E-posta taslağınız posta uygulamanızda hazır. Talebinizi tamamlamak için kontrol edip gönderin.')}else if(route.value==='whatsapp'&&approvedWhatsapp){window.open(`https://wa.me/${approvedWhatsapp}?text=${encodeURIComponent(body)}`,'_blank','noopener,noreferrer');inquiryStatus.textContent=bilingual('Continue in WhatsApp. Review and send the message to complete your inquiry.','WhatsApp üzerinden devam edin. Talebinizi tamamlamak için mesajı kontrol edip gönderin.')}else{const url=URL.createObjectURL(new Blob(['\uFEFF'+body],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`mahjoub-academy-inquiry-${courseLanguage()}.txt`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);inquiryStatus.textContent=bilingual('Inquiry draft downloaded. Nothing has been sent. Keep the file until the enrollment contact is available.','Talep taslağı indirildi. Hiçbir şey gönderilmedi. Başvuru iletişim bilgileri hazır olana kadar dosyayı saklayın.')}});
